def 还原授权错误(错误文本):
    if not 错误文本.startswith("["):
        return {"码": "", "消息": 错误文本}
    结束 = 错误文本.find("]")
    if 结束 < 0:
        return {"码": "", "消息": 错误文本}
    return {"码": 错误文本[1:结束], "消息": 错误文本[结束 + 2:]}

