# 校验 IPC 消息形状：必须为字典，含 channel（在名词表内）+ payload
#   返回 {"通过":真} / {"通过":假,"原因":...}
段落 校验IPC消息(消息):
  如果 是字典(消息) == 假:
    返回 {"通过": 假, "原因": "IPC消息须为字典"}
  如果 消息.包含("channel") == 假:
    返回 {"通过": 假, "原因": "IPC消息缺少 channel 字段"}
  如果 消息.包含("payload") == 假:
    返回 {"通过": 假, "原因": "IPC消息缺少 payload 字段"}
  设 通道 为 消息["channel"]
  如果 是字符串(通道) == 假:
    返回 {"通过": 假, "原因": "channel 须为字符串"}
  如果 字符串长度(通道) == 0:
    返回 {"通过": 假, "原因": "channel 为空串"}
  如果 是合法IPC通道(通道) == 假:
    返回 {"通过": 假, "原因": "未知 IPC 通道: " + 通道}
  返回 {"通过": 真, "原因": 空}

# 对外转移入口：合法 -> {"成功":真,"新状态":...}；非法 -> {"成功":假,"原因":...}（fail-closed）
段落 窗口状态转移(当前态, 事件):
  如果 是合法窗口状态(当前态) == 假:
    返回 {"成功": 假, "原因": "非法当前窗口状态: " + 当前态, "新状态": 空}
  设 新态 为 决策窗口转移(当前态, 事件)
  如果 新态 == 空:
    返回 {"成功": 假, "原因": "非法转移 " + 当前态 + " -[" + 事件 + "]-> ?", "新状态": 当前态}
  返回 {"成功": 真, "新状态": 新态, "原因": 空}

